# Silent Updates - experiment 3b: which GitHub projects load the models that changed?
# ------------------------------------------------------------------------------------
# Kaggle or Colab. Internet ON. No GPU. About 40 minutes (GitHub rate-limits code search
# to roughly 10 queries a minute, and we make one query per model).
#
# SETUP - the token must come from a secret store, never pasted into a notebook cell:
#   Kaggle:  Add-ons > Secrets > new secret named GITHUB_TOKEN, toggled on for this notebook
#   Colab:   key icon in the left sidebar > new secret named GITHUB_TOKEN, notebook access on
# The token needs the `public_repo` scope and nothing else.
#
# Cell 1: !pip -q install -U requests
# Cell 2: this file.
#
# Why this and not PeaTMOSS: PeaTMOSS covers 2,530 mostly foundation models, while this corpus is
# fine-tuned classifiers, so the overlap would be thin; and its metadata release is 8.32 GB behind
# Globus. Code search asks our exact question against current data.
#
# What it measures, per model: how many public files on GitHub name it, and in how many of the
# returned matches a revision is pinned nearby. A matched control group of models that did NOT
# change is included, so the comparison is like for like rather than a bare count.
# ------------------------------------------------------------------------------------
import os, json, re, time, random, sys

PLATFORM = "kaggle" if os.path.exists("/kaggle/working") else "colab" if os.path.exists("/content") else "local"
TOKEN = os.environ.get("GITHUB_TOKEN")
if not TOKEN and PLATFORM == "kaggle":
    try:
        from kaggle_secrets import UserSecretsClient; TOKEN = UserSecretsClient().get_secret("GITHUB_TOKEN")
    except Exception as e: print("kaggle secret lookup failed:", type(e).__name__)
if not TOKEN and PLATFORM == "colab":
    try:
        from google.colab import userdata; TOKEN = userdata.get("GITHUB_TOKEN")
    except Exception as e: print("colab secret lookup failed:", type(e).__name__)
if not TOKEN:
    print("GITHUB_TOKEN not found. Add it as a secret (see the header) and re-run. Stopping.")
    sys.exit(0)
if PLATFORM == "kaggle": os.chdir("/kaggle/working")

