S = requests.Session()
S.headers.update({"Authorization": f"Bearer {TOKEN}",
                  "Accept": "application/vnd.github.text-match+json",
                  "X-GitHub-Api-Version": "2022-11-28",
                  "User-Agent": "silent-updates-study"})
PIN = re.compile(r"revision\s*=|revision\"\s*:|\b[0-9a-f]{40}\b")
BUDGET_S = 70 * 60
t0 = time.time()

def search(model):
    """One code-search query. Returns (total_files, matches_with_a_pin, sample_repos)."""
    q = f'"{model}" language:python'
    for attempt in range(6):
        if time.time() - t0 > BUDGET_S: raise TimeoutError("budget")
        r = S.get("https://api.github.com/search/code",
                  params={"q": q, "per_page": 30}, timeout=45)
        if r.status_code == 200:
            j = r.json()
            items = j.get("items", [])
            pinned, repos = 0, []
            for it in items:
                frag = " ".join(m.get("fragment", "") for m in it.get("text_matches", []))
                if PIN.search(frag): pinned += 1
                repos.append(it["repository"]["full_name"])
            return j.get("total_count", 0), pinned, len(items), sorted(set(repos))
        if r.status_code in (403, 429):                      # secondary rate limit
            wait = int(r.headers.get("retry-after", 0)) or min(60, 8 * (attempt + 1))
            time.sleep(wait); continue
        if r.status_code == 422:                             # query rejected
            return None, None, None, []
        time.sleep(5)
    return None, None, None, []

print(f"\n{'model':<52s} {'files':>7s} {'shown':>6s} {'pinned':>7s}  group")
done = 0
for mid in QUEUE:
    if mid in RES: continue
    grp = "rewritten" if mid in REWRITTEN else "changed" if mid in CHANGED else "control"
    try:
        total, pinned, shown, repos = search(mid)
    except TimeoutError:
        print("STOPPING: time budget reached. Re-run to resume."); break
    except Exception as e:
        RES[mid] = dict(id=mid, group=grp, error=f"{type(e).__name__}: {str(e)[:120]}")
        print(f"{mid[:52]:<52s} {'ERR':>7s} {type(e).__name__}")
        json.dump(RES, open(RES_PATH, "w")); time.sleep(6.5); continue
    RES[mid] = dict(id=mid, group=grp, files=total, shown=shown, pinned=pinned, repos=repos[:30])
    done += 1
    if done % 5 == 0 or total:
        print(f"{mid[:52]:<52s} {str(total):>7s} {str(shown):>6s} {str(pinned):>7s}  {grp}")
    json.dump(RES, open(RES_PATH, "w"))
    time.sleep(6.5)                                           # stay under ~10 queries/minute

# ---------------------------------------------------------------- summary
ok = [r for r in RES.values() if r.get("files") is not None]
print("\n" + "=" * 78)
print(f"queried {len(RES)} models | usable {len(ok)}")
for grp in ("rewritten", "changed", "control"):
    g = [r for r in ok if r["group"] == grp]
    if not g: continue
    used = [r for r in g if r["files"] > 0]
    files = sum(r["files"] for r in g)
    repos = set().union(*[set(r["repos"]) for r in g]) if g else set()
    shown = sum(r["shown"] or 0 for r in g); pinned = sum(r["pinned"] or 0 for r in g)
    print(f"  {grp:<10s} models {len(g):4d} | with >=1 file {len(used):4d} | files {files:7d} | "
          f"distinct repos seen {len(repos):5d} | pinned {pinned}/{shown}")
print("\nmost-depended-on models whose checkpoint was rewritten:")
for r in sorted([r for r in ok if r["group"] == "rewritten"], key=lambda r: -r["files"])[:12]:
    print(f"   {r['id'][:52]:<52s} {r['files']:6d} files   e.g. {(r['repos'] or ['-'])[0]}")

json.dump(RES, open(RES_PATH, "w"))
print("\n---------- RESULTS JSON (copy this if the output tab fails) ----------")
print(json.dumps({k: {kk: vv for kk, vv in v.items() if kk != "repos"} for k, v in RES.items()}))
try:
    import shutil; shutil.make_archive("su_gh_results", "zip", ".", OUT); print("\nsaved su_gh_results.zip")
except Exception as e: print("zip failed:", e)
